INSERT INTO `conteneurs` (`id`, `reference`, `categorie_id`, `type_conteneur`, `dimensions`, `pieds`, `type_pied`, `dimension_pieds`, `dimension_metres`, `longueur`, `largeur`, `hauteur`, `poids`, `capacite`, `prix_achat`, `prix_vente`, `prix_location_jour`, `quantite_stock`, `quantite_min_alerte`, `etat`, `annee_fabrication`, `certificat_csc`, `description`, `caracteristiques`, `images`, `image_principale`, `images_secondaires`, `statut`, `created_at`, `updated_at`, `description_en`, `description_es`, `description_fr`, `description_de`, `description_nl`, `description_fi`, `description_ch`) VALUES
(26, 'CONT-8DC-2024-2125451', 1, 'standard', '8DC 2.44 metri', '8', '', NULL, NULL, 2.44, 2.20, 2.26, 1300.00, 9.87, 2400.00, 2450.00, 400.00, 1000, 100, 'neuf', '2024', 1, 'Contenitore di stoccaggio 8DC 2125451 – Soluzione nuova e rappresentativa per cortile domestico o spazio commerciale.\r\n\r\nTutti i contenitori sono fabbricati in Asia con garanzia di resistenza alle intemperie per 50 anni. Le foto corrispondono al contenitore pubblicizzato.\r\n\r\nCARATTERISTICHE TECNICHE:\r\n- Dimensioni esterne: 2,44 m (L) × 2,2 m (l) × 2,26 m (H)\r\n- Dimensioni interne: 2,28 m (L) × 2,11 m (l) × 2,05 m (H)\r\n- Colore: Blu RAL5010\r\n- 2 porte con serratura di sicurezza centrale\r\n- Ventilazione aggiuntiva sui lati\r\n- 2 ganci per contenitore di stoccaggio (possibilità di 3 serrature)\r\n\r\nSERVIZI INCLUSI:\r\n- Noleggio possibile su accordo\r\n- Trasporto con camion gru, side loader o RAM backloader per luoghi difficili\r\n- Stoccaggio gratuito fino a 6 mesi dopo l\'acquisto\r\n- Garanzia migliore prezzo\r\n- Opzione \"Acquista ora, paga dopo\" disponibile\r\n\r\nCONDIZIONI DI PAGAMENTO:\r\n- Clienti privati: finanziamento tramite Inbank.ee (codice \"KONTEINER\")\r\n- Clienti business: finanziamento tramite Tenor.ee\r\n\r\nSeguici su Facebook e Instagram per le ultime offerte!', '{\"matiere\":\"Acciaio\",\"couleur\":\"Blu RAL5010\",\"portes\":\"2 porte con serratura di sicurezza centrale e apertura facile\"}', NULL, 'uploads/standard/principales/principale_standard_692f57ca4134b_1764710346.jpg', '[\"uploads\\/standard\\/secondaires\\/secondaire_standard_692f5dbd8b15e_1764711869.jpg\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_692f5dbd8b635_1764711869.jpg\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_692f5dbd8bb72_1764711869.jpg\"]', 'disponible', '2025-12-02 21:19:06', '2025-12-03 19:14:26', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(27, '8DC Storage container – 2252412', 1, 'standard', '8DC (2.44m) - Storage container', '8', '', NULL, NULL, 2.44, 2.20, 2.26, 1300.00, NULL, 2000.00, 2450.00, NULL, 1000, 100, 'neuf', '2024', 1, 'La vendita di container da magazzino 2252412 è una soluzione nuova e rappresentativa per un cortile domestico o uno spazio commerciale.\r\nTutti i container sono prodotti in Asia.\r\nLe immagini corrispondono al container pubblicizzato.\r\nIl container da magazzino ha un totale di due collegamenti, che sono più alti dei collegamenti del container marittimo e possono anche essere dotati di 3 serrature.\r\nLa protezione della serratura si trova al centro delle due porte.\r\nVentilazione aggiuntiva sui lati.\r\nUsa prima, paga dopo - Inbank.ee e il codice sconto è \"KONTEINER\".\r\nÈ possibile noleggiare container marittimi previo accordo.\r\nMiglior prezzo garantito!\r\nDimensioni esterne: 2,44 m di lunghezza x 2,20 m di larghezza x 2,26 m di altezza.\r\nDimensioni interne: 2,28 m di lunghezza x 2,11 m di larghezza x 2,05 m di altezza.\r\nOpzione \"Acquista ora, paga dopo\" disponibile:\r\nPer i clienti al dettaglio tramite il nostro partner Inbank.ee utilizzando il codice di riferimento \"KONTEINER\".\r\nPer i clienti aziendali tramite il nostro partner Tenor.ee\r\nFacciamo sempre la migliore offerta per un container equivalente.\r\nVendita container di stoccaggio 2252412 - Trasporto e sollevamento?\r\nDopo aver scelto un container adatto, possiamo anche offrire il trasporto.\r\nDi solito utilizziamo camion gru o caricatori laterali per il trasporto.\r\nUtilizziamo il backloader RAM per raggiungere i luoghi più difficili.\r\nDopo l\'acquisto, conserviamo il tuo container nel nostro terminal gratuitamente per un massimo di sei mesi.\r\nÈ sempre possibile concordare un periodo più lungo.\r\nAd esempio, se il luogo non è ancora pronto o accessibile per la consegna del container.\r\nCaratteristiche:\r\n- 2,44 metri\r\n- Dimensioni del container\r\n- Porta facile da aprire\r\n- Protezione della serratura\r\n- Chiudibile a chiave\r\n\r\nTradotto con DeepL.com (versione gratuita)', '{\"matiere\":\"Acciaio (probabilmente marittimo)\",\"couleur\":\"grigio\",\"portes\":\"2 porte con apertura facilitata + serratura centrale Ventilazione laterale supplementare\"}', NULL, 'uploads/standard/principales/principale_standard_692f737e277dc_1764717438.jpg', '[\"uploads\\/standard\\/secondaires\\/secondaire_standard_692f737e28fd5_1764717438.jpg\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_692f737e2a0f2_1764717438.jpg\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_692f737e2a95f_1764717438.jpg\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_692f737e2f08f_1764717438.jpg\"]', 'disponible', '2025-12-02 23:17:18', '2025-12-03 19:12:43', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(28, 'CONT-2024-7178891', 1, 'standard', '10DC', '10', '', NULL, NULL, 3.00, 2.44, 2.59, 1500.00, 19.00, 2800.00, 2990.00, 500.00, 3000, 500, 'neuf', NULL, 0, 'Contenitore di stoccaggio 10DC - 7178891 - Nuovo contenitore di stoccaggio\r\nIl contenitore di stoccaggio 7178891 è una soluzione nuova e rappresentativa per un cortile domestico o uno spazio commerciale.\r\nTutti i contenitori sono prodotti in Asia.\r\n\r\nGaranzia di resistenza alle intemperie per 50 anni.\r\nIl container di stoccaggio ha un totale di due chiusure, più alte di quelle del container marittimo, e può anche essere dotato di 3 serrature.\r\nLa serratura si trova al centro delle due porte.\r\nVentilazione supplementare sui lati.\r\nPossibilità di noleggio container marittimo previo accordo.\r\nGaranzia del miglior prezzo!\r\nOpzione \"Acquista ora, paga dopo\" disponibile.\r\n\r\nTrasporto e sollevamento:\r\nPer il trasporto utilizziamo generalmente un camion gru o caricatori laterali.\r\nUtilizziamo il RAM backloader per raggiungere i luoghi più difficili.\r\n\r\nStoccaggio gratuito fino a sei mesi dopo l\'acquisto.\r\nPeriodo più lungo possibile previo accordo.\r\nGaranzia del miglior prezzo: facciamo sempre l\'offerta migliore per il container.', '{\"matiere\":\"acciaio\",\"couleur\":\"avorio RAL1015\",\"portes\":\"2 porte con chiusura facile\"}', NULL, 'uploads/standard/principales/principale_standard_69309984c954e_1764792708.jpg', '[\"uploads\\/standard\\/secondaires\\/secondaire_standard_69309984cc7b6_1764792708.jpg\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_69309984cccc4_1764792708.jpg\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_69309984cd1aa_1764792708.jpg\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_69309984cd630_1764792708.jpg\"]', 'disponible', '2025-12-03 20:11:48', '2025-12-03 20:11:48', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(29, 'REF reefer container Thermo King 5555680', 1, 'reefer', '20 pieds (20HC = 20 pieds High Cube)', '20', 'DC', NULL, NULL, 6.00, 2.44, 2.90, 2300.00, 33.00, 9000.00, 9900.00, 500.00, 100, 10, 'neuf', '2024', 1, 'Container refrigerato 20HC / REF Thermo King 5555680\r\n\r\nContainer refrigerati – Ampia scelta, ottimi prezzi\r\nAbbiamo una vasta gamma di container refrigerati 20HC et 40HC disponibili a magazzino.\r\nContainer refrigerati nuovi con attrezzatura, senza porte: 9900 € + IVA.\r\nMotore refrigerante nuovo: 7900 € + IVA (completo di telaio).\r\n\r\nRealizziamo soluzioni su misura per le vostre esigenze: sono disponibili diverse porte per celle frigorifere, porte sollevabili e opzioni di isolamento.\r\n\r\nOpzione \"Acquista ora, paga dopo\":\r\n- Per i clienti privati tramite il nostro partner Inbank.ee\r\n- Per i clienti professionali tramite il nostro partner Tenor.ee\r\n\r\nNoleggio di container refrigerati disponibili immediatamente: container refrigerati con porte per celle frigorifere, porte standard, container di raffreddamento.\r\n\r\nTrasporto e installazione:\r\nForniamo preventivi di trasporto e generalmente utilizziamo una gru o un sideloader per la consegna.\r\n\r\nGaranzia del miglior prezzo: offriamo sempre la migliore offerta per un container equivalente.\r\n\r\nCaratteristiche tecniche:\r\n- 6 metri\r\n- Colore: bianco\r\n- Isolato\r\n- Chiudibile a chiave', '{\"matiere\":\"acciaio + isolamento\",\"couleur\":\"bianco\",\"portes\":\"2 porte per cella frigorifera\"}', NULL, 'uploads/reefer/principales/principale_reefer_6959563382af1_1767462451.jpg', '[\"uploads\\/reefer\\/secondaires\\/secondaire_reefer_69595633860f2_1767462451.png\",\"uploads\\/reefer\\/secondaires\\/secondaire_reefer_69595633864b9_1767462451.jpg\",\"uploads\\/reefer\\/secondaires\\/secondaire_reefer_6959563388f67_1767462451.jpg\",\"uploads\\/reefer\\/secondaires\\/secondaire_reefer_69595633894fc_1767462451.jpg\"]', 'disponible', '2026-01-03 17:47:31', '2026-01-03 18:27:40', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(30, '20DC Storage container 0188961 – TALLINN', 1, 'standard', '20DC', '20', 'DC', NULL, NULL, 6.00, 2.44, 2.59, 2300.00, 33.20, 2290.00, 2390.00, 500.00, 100, 10, 'neuf', '2024', 1, '', '{\"matiere\":\"acciaio\",\"couleur\":\"nero\",\"portes\":\"2 porte con serratura centrale, 3+ chiusure possibili\"}', NULL, 'uploads/standard/principales/principale_standard_6959b95636c05_1767487830.png', '[\"uploads\\/standard\\/secondaires\\/secondaire_standard_6959b956381f0_1767487830.jpg\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_6959b956393e5_1767487830.jpg\"]', 'disponible', '2026-01-04 00:50:30', '2026-01-04 00:50:30', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(31, 'Rental Container nr 108', 16, 'standard', '20DC', '20', 'DC', NULL, NULL, 6.00, 2.44, 2.59, 2300.00, 33.00, 100.00, 300.00, 30.00, 100, 5, 'occasion', NULL, 1, 'Contenitore a noleggio n. 108 \r\nNoleggiamo contenitori di tutte le dimensioni: 20DC, 40HC, 45HCPW.\r\nDisponiamo di un\'ampia scelta di contenitori in loco, sempre disponibili in diversi colori.\r\nIl contenitore a noleggio più popolare è quello da 6 metri (20DC).\r\nIl vantaggio principale di questo contenitore è la sua dimensione e il suo peso.\r\nIl container da 6 metri può essere manovrato e sollevato con una gru in un luogo adatto alle esigenze del cliente.\r\n\r\nIl container può essere utilizzato per riporre mobili, materiali da costruzione, attrezzature stagionali o qualsiasi altro oggetto.\r\nIl container è a tenuta di polvere e robusto, uno spazio aggiuntivo ideale per le riparazioni.\r\nPerché affittare un garage o una rimessa quando puoi spostare il container nel tuo cortile?\r\nOltre allo stoccaggio, i container possono essere utilizzati anche per la pubblicità.\r\nSe desiderate far conoscere la vostra attività, incolleremo o dipingeremo i container con i vostri colori e li trasporteremo sul posto.\r\nTrasporto e sollevamento?\r\nDopo aver scelto un container adeguato, possiamo anche offrire il servizio di trasporto.\r\nGeneralmente utilizziamo autogru o caricatori laterali per il trasporto.\r\nUtilizziamo il RAM backloader per raggiungere i luoghi più difficili.\r\nGaranzia del miglior prezzo: facciamo sempre l\'offerta migliore per il container.\r\nCaratteristiche tecniche:\r\n- 6 metri\r\n- Colore: giallo\r\n- Tasche per carrello elevatore\r\n- Chiudibile a chiave\r\n- Prezzo: 300 € + IVA', '{\"matiere\":\"acciaio corten\",\"couleur\":\"giallo\",\"portes\":\"2 porte scorrevoli con tasche per carrello elevatore\"}', NULL, 'uploads/standard/principales/principale_standard_695a345c10987_1767519324.jpg', '[\"uploads\\/standard\\/secondaires\\/secondaire_standard_695a345c10efe_1767519324.jpg\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_695a345c1150c_1767519324.jpg\"]', 'disponible', '2026-01-04 09:35:24', '2026-02-06 07:55:16', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(32, 'Office Cabin Containex 3D – 0088', 8, 'standard', 'Cabine bureau portable', 'autre', 'DC', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 200.00, 300.00, NULL, 100, 5, 'neuf', NULL, 0, 'Ufficio Cabin Containex 3D – Cabina ufficio portatile\r\n\r\nDESCRIZIONE GENERALE:\r\nCabina ufficio portatile di alta qualità con certificazione CE. Struttura assemblata con bulloni che offre una resistenza superiore rispetto alle strutture saldate. Ideale per uso ufficio, casa estiva, spazio commerciale o punto vendita.\r\n\r\nCARATTERISTICHE TECNICHE:\r\n- Colore esterno: grigio chiaro RAL7035 (opzioni speciali disponibili)\r\n- Isolamento: pareti - schiuma PU 45-60 mm | tetto - lana minerale 100 mm | pavimento - lana minerale 100 mm o pannelli PU 60 mm\r\n- Copertura: lamiera laminata stagnata o verniciata\r\n- Porta: 1 porta anteriore (875 mm di larghezza, apertura 811 mm, altezza 2065 mm)\r\n- Finestre: 1 finestra standard (opzioni di posizionamento personalizzato)\r\n- Illuminazione: 2 lampade\r\n- Elettricità: 1 quadro elettrico, 2 prese, 1 interruttore\r\n\r\nOPZIONI DISPONIBILI:\r\n- Posizionamento personalizzato di finestre e porte (max 1 settimana)\r\n- Finestre panoramiche (max 4 settimane)\r\n- Rivestimento interno in legno\r\n- Diversi tipi di finestre, porte, lampade\r\n- Altezze variabili\r\n- Prese aggiuntive su richiesta\r\n\r\nINSTALLAZIONE E CONSEGNA:\r\n- Installazione: meno di 30 minuti\r\n- Consegna: possibile in giornata per i modelli standard\r\n- Nessuna fondazione necessaria\r\n- Installazione secondo le esigenze del cliente\r\n\r\nNOTA IMPORTANTE:\r\nSi tratta di un modello 3D e di una struttura per cabina, non della vendita della sola struttura! Le cabine portatili vendute sono sempre complete e di alta qualità.', '{\"matiere\":\"acciaio + isolamento PU\\/materiale minerale\",\"couleur\":\"grigio chiaro RAL7035\",\"portes\":\"1 porta anteriore (875 mm) + opzioni finestre\\/porte personalizzate\"}', NULL, 'uploads/standard/principales/principale_standard_695be95c33de0_1767631196.jpg', '[\"uploads\\/standard\\/secondaires\\/secondaire_standard_695be95c34f53_1767631196.jpg\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_695be95c35423_1767631196.jpg\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_695be95c358ab_1767631196.jpg\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_695be95c35d56_1767631196.jpg\"]', 'disponible', '2026-01-05 16:39:56', '2026-01-05 16:39:56', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(33, 'Office Cabin Containex Basic Anthracite –', 8, 'standard', '20 pieds (Standard DC)', '', 'DC', NULL, NULL, 6.00, 2.44, 2.59, 2300.00, 36.50, NULL, 2500.00, 100.00, 100, 5, 'neuf', NULL, 1, 'Ufficio Cabina Containex Basic Antracite\r\n\r\nCabina ufficio Containex Basic Antracite – Modello base Containex, lunghezza 6 metri, larghezza 2,44 metri e altezza 2,6 metros.\r\n\r\nCARATTERISTICHE TECNICHE:\r\n- Dimensioni esterne: 6 m (L) × 2,44 m (l) × 2,59 m (H)\r\n- Dimensioni interne: 5,85 m (L) × 2,30 m (l) × 2,34 m (H)\r\n- Capacità di carico del pavimento: 200 kg/m² (può essere aumentata)\r\n- Colore: grigio antracite RAL7016 (telaio e pannelli)\r\n- Tipo: DC Standard (doppio container)\r\n\r\nISOLAMENTO:\r\n- Pareti: schiuma PU 45 mm (equivalente a 60 mm di lana)\r\n- Tetto: lana minerale 100 mm\r\n- Pavimento: pannoli PU 60 mm\r\n\r\nDOTAZIONE STANDARD:\r\n- 1 finestra apribile (posizione di ventilazione o apertura completa)\r\n- 1 porta d\'ingresso (apribile verso l\'esterno)\r\n- 2 prese elettriche\r\n- 1 interruttore luce\r\n- 1 quadro elettrico\r\n- 2 lampade\r\n- Riscaldamento di qualità con marchio CE\r\n- Collegamento elettrico: 230V/32A/3 poli\r\n\r\nDETTAGLI PORTA E FINESTRA:\r\n- Larghezza porta: 875 mm\r\n- Apertura porta: 811 mm\r\n- Altezza apertura porta: 2065 mm\r\n- Altezza finestra dal pavimento: 870 mm\r\n\r\nCOSTRUZIONE:\r\n- Telaio imbullonato (vantaggio rispetto ai telai saldati)\r\n- Tetto in lamiera zincata o verniciata\r\n- Installazione rapida (<30 minuti)\r\n- Non sono necessarie fondamenta\r\nUTILIZZI:\r\n- Ufficio temporaneo/permanente\r\n- Cottage stagionale\r\n- Punto vendita\r\n- Spazio commerciale\r\n- Mini-casa\r\n\r\nSERVIZI DISPONIBILI:\r\n- Vendita: 4890 € + IVA\r\n- Noleggio a breve/lungo termine\r\n- Installazione inclusa', '{\"matiere\":\"acciaio + isolamento\",\"couleur\":\"grigio antracite RAL7016\",\"portes\":\"1 porta d\'ingresso + 1 finestra apribile\"}', NULL, 'uploads/standard/principales/principale_standard_695bf7f232a21_1767634930.jpg', '[\"uploads\\/standard\\/secondaires\\/secondaire_standard_695bf7f233301_1767634930.jpg\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_695bf7f2337a5_1767634930.jpg\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_695bf7f234316_1767634930.jpeg\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_695bf7f234867_1767634930.jpg\"]', 'disponible', '2026-01-05 17:42:10', '2026-03-05 22:34:58', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(34, 'Conteneur maritime 40HC', 1, 'standard', '40HC', '40', 'HC', NULL, NULL, 12.19, 2.44, 2.59, 3700.00, 67.00, NULL, 4990.00, NULL, 24, 5, 'neuf', NULL, 0, 'Vente de Conteneur Maritime – 40 Pieds High Cube « NEUF » SENS UNIQUE\r\nConteneur maritime « NEUF » ALLER SIMPLE\r\nTous les conteneurs sont fabriqués en Asie.\r\nLes conteneurs neufs arrivent à notre terminal avec un chargement aller simple afin d\'éviter les frais de transport qui seraient autrement ajoutés au prix du conteneur.\r\n\r\nGarantie de résistance aux intempéries pendant 50 ans.\r\nLes images correspondent au contenant présenté dans la publicité.\r\nLe conteneur peut présenter de légers défauts esthétiques dus au transport.\r\nLe conteneur maritime possède un total de quatre maillons et peut être équipé de plus de 3 serrures.\r\nLe conteneur de stockage possède un total de trois maillons, qui sont plus hauts que ceux du conteneur maritime et peuvent également être équipés de plus de 3 serrures.\r\nLa protection de la serrure est située au milieu des deux portes.\r\nVentilation supplémentaire sur les côtés.\r\nLa location de conteneurs maritimes est possible sur accord.\r\nGarantie du meilleur prix !\r\n\r\nNous faisons toujours la meilleure offre pour un conteneur équivalent.\r\n\r\nVente de conteneurs maritimes MIIU3049105 « NOUVEAU » ALLER SIMPLE – Transport et levage ?\r\nAprès avoir choisi le conteneur adapté, nous pouvons également assurer le transport.\r\nNous utilisons généralement  des camions-grues  ou  des chargeuses latérales  .  Pour les accès les plus difficiles,\r\nnous avons recours au  chargeur dorsal RAM .\r\n\r\nAprès votre achat, nous stockons gratuitement votre conteneur dans notre terminal pendant six mois maximum.\r\n\r\nIl est toujours possible de convenir d\'un délai plus long,\r\npar exemple si le site n\'est pas encore prêt ou accessible pour la livraison du conteneur.\r\nDans ce cas, le prix du conteneur reste inchangé et vous avez la garantie de recevoir le conteneur sélectionné à la date convenue.\r\n\r\nGarantie du meilleur prix – nous vous faisons toujours la meilleure offre pour le conteneur.\r\n\r\nLivraison offerte\r\nPaiement sécurisé\r\nRetours sous 30 jours\r\nDélai de Livraison 8 à 12 Jours ouvrés', '{\"couleur\":\"vert\",\"portes\":\"2\"}', NULL, 'uploads/standard/principales/principale_standard_695c17b4166bc_1767643060.webp', '[\"uploads\\/standard\\/secondaires\\/secondaire_standard_695c17b41c476_1767643060.webp\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_695c17b422c25_1767643060.webp\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_695c17b428311_1767643060.webp\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_695c17b42aa9d_1767643060.webp\"]', 'disponible', '2026-01-05 19:57:40', '2026-01-05 19:57:40', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(35, 'Conteneur maritime 40HC TALLINN (2022)', 1, 'standard', '40HC', '40', 'HC', NULL, NULL, 12.19, 2.44, 2.59, 3700.00, 67.00, NULL, 4090.00, NULL, 96, 58, 'neuf', NULL, 1, 'Vente de Conteneur Maritime – 40 Pieds High Cube « NEUF » SENS UNIQUE\r\nConteneur maritime « NEUF » ALLER SIMPLE\r\nTous les conteneurs sont fabriqués en Asie.\r\nLes conteneurs neufs arrivent à notre terminal avec un chargement aller simple afin d\'éviter les frais de transport qui seraient autrement ajoutés au prix du conteneur.\r\n\r\nGarantie de résistance aux intempéries pendant 50 ans.\r\nLes images correspondent au contenant présenté dans la publicité.\r\nLe conteneur peut présenter de légers défauts esthétiques dus au transport.\r\nLe conteneur maritime possède un total de quatre maillons et peut être équipé de plus de 3 serrures.\r\nLe conteneur de stockage possède un total de trois maillons, qui sont plus hauts que ceux du conteneur maritime et peuvent également être équipés de plus de 3 serrures.\r\nLa protection de la serrure est située au milieu des deux portes.\r\nVentilation supplémentaire sur les côtés.\r\nLa location de conteneurs maritimes est possible sur accord.\r\nGarantie du meilleur prix !\r\n\r\nNous faisons toujours la meilleure offre pour un conteneur équivalent.\r\n\r\nVente de conteneurs maritimes MIIU3049105 « NOUVEAU » ALLER SIMPLE – Transport et levage ?\r\nAprès avoir choisi le conteneur adapté, nous pouvons également assurer le transport.\r\nNous utilisons généralement  des camions-grues  ou  des chargeuses latérales  .  Pour les accès les plus difficiles,\r\nnous avons recours au  chargeur dorsal RAM .\r\n\r\nAprès votre achat, nous stockons gratuitement votre conteneur dans notre terminal pendant six mois maximum.\r\n\r\nIl est toujours possible de convenir d\'un délai plus long,\r\npar exemple si le site n\'est pas encore prêt ou accessible pour la livraison du conteneur.\r\nDans ce cas, le prix du conteneur reste inchangé et vous avez la garantie de recevoir le conteneur sélectionné à la date convenue.\r\n\r\nGarantie du meilleur prix – nous vous faisons toujours la meilleure offre pour le conteneur.\r\n\r\nLivraison offerte\r\nPaiement sécurisé\r\nRetours sous 30 jours\r\nDélai de Livraison 8 à 12 Jours ouvrés', '{\"couleur\":\"Bleue\",\"portes\":\"2\"}', NULL, 'uploads/standard/principales/principale_standard_695d4e924b637_1767722642.webp', '[\"uploads\\/standard\\/secondaires\\/secondaire_standard_695d4e924eb20_1767722642.webp\"]', 'disponible', '2026-01-06 18:04:02', '2026-01-06 18:04:02', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
