(38, 'Conteneur de stockage 20DC TALLINN (dommages esthé', 1, 'standard', '20′ (6 mètres)', '20', 'DC', NULL, NULL, 6.06, 2.44, 2.59, 2200.00, 33.00, NULL, 2390.00, NULL, 42, 5, 'neuf', NULL, 0, 'Vente de conteneurs maritimes « NEUF » SENS UNIQUE\r\nVente de conteneurs maritimes. Tous nos conteneurs sont fabriqués en Asie. Les conteneurs neufs arrivent à notre terminal avec un chargement à sens unique afin d\'éviter les frais de transport qui seraient autrement répercutés sur le prix du conteneur.\r\n\r\nGarantie de résistance aux intempéries pendant 50 ans.\r\nLes images correspondent au contenant présenté dans la publicité.\r\nLe conteneur peut présenter de légers défauts esthétiques dus au transport.\r\nLe conteneur maritime possède un total de four maillons et peut être équipé de plus de 3 serrures.\r\nLe conteneur de stockage possède un total de trois maillons, qui sont plus hauts que ceux du conteneur maritime et peuvent également être équipés de plus de 3 serrures.\r\nLa protection de la serrure est située au milieu des deux portes.\r\nVentilation supplémentaire sur les côtés.\r\nLa location de conteneurs maritimes est possible sur accord.\r\nGarantie du meilleur prix !\r\nNous faisons toujours la meilleure offre pour un conteneur équivalent.\r\n\r\nVente de conteneurs maritimes – Transport et levage ?\r\nAprès avoir choisi le conteneur adapté, nous assurons également son transport.\r\nNous utilisons généralement  des camions-grues  ou  des chargeurs latéraux  .  Pour les zones les plus difficiles d\'accès,\r\nnous avons recours au  chargeur RAM\r\n. Après votre achat, nous stockons gratuitement votre conteneur dans notre terminal pendant six mois maximum,\r\nnotamment si le site de livraison n\'est pas encore prêt ou accessible.\r\n\r\nGarantie du meilleur prix – nous vous faisons toujours la meilleure offre pour le conteneur.', '{\"couleur\":\"Bleu\",\"portes\":\"Porte à ouverture facile\"}', NULL, 'uploads/standard/principales/principale_standard_695d6754df257_1767728980.webp', '[\"uploads\\/standard\\/secondaires\\/secondaire_standard_695d6754e5996_1767728980.webp\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_695d6754ebcdd_1767728980.webp\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_695d6754f2315_1767728980.webp\"]', 'disponible', '2026-01-06 19:49:41', '2026-01-06 19:49:41', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(39, 'Conteneur de stockage 20DC – TALLINN', 1, 'standard', '20′ (6 mètres)', '20', 'DC', NULL, NULL, 6.06, 2.44, 2.59, 2200.00, 33.00, NULL, 2690.00, NULL, 42, 5, 'neuf', NULL, 0, 'Vente de conteneurs maritimes « NEUF » SENS UNIQUE\r\nVente de conteneurs maritimes. Tous nos conteneurs sont fabriqués en Asie. Les conteneurs neufs arrivent à notre terminal avec un chargement à sens unique afin d\'éviter les frais de transport qui seraient autrement répercutés sur le prix du conteneur.\r\n\r\nGarantie de résistance aux intempéries pendant 50 ans.\r\nLes images correspondent au contenant présenté dans la publicité.\r\nLe conteneur peut présenter de légers défauts esthétiques dus au transport.\r\nLe conteneur maritime possède un total de four maillons et peut être équipé de plus de 3 serrures.\r\nLe conteneur de stockage possède un total de trois maillons, qui sont plus hauts que ceux du conteneur maritime et peuvent également être équipés de plus de 3 serrures.\r\nLa protection de la serrure est située au milieu des deux portes.\r\nVentilation supplémentaire sur les côtés.\r\nLa location de conteneurs maritimes est possible sur accord.\r\nGarantie du meilleur prix !\r\nNous faisons toujours la meilleure offre pour un conteneur équivalent.\r\n\r\nVente de conteneurs maritimes – Transport et levage ?\r\nAprès avoir choisi le conteneur adapté, nous pouvons également assurer le transport.\r\nNous utilisons généralement  des camions-grues  ou  des chargeuses latérales  .  Pour les accès les plus difficiles,\r\nnous avons recours au  chargeur dorsal RAM .\r\n\r\nAprès votre achat, nous stockons gratuitement votre conteneur dans notre terminal pendant six mois maximum.\r\n\r\nIl est toujours possible de convenir d\'un délai plus long,\r\npar exemple si le site n\'est pas encore prêt ou accessible pour la livraison du conteneur.\r\nDans ce cas, le prix du conteneur reste inchangé et vous avez la garantie di ricevere il contenitore selezionato alla data convenuta.\r\n\r\nGarantie du meilleur prix – nous vous faisons toujours la meilleure offre pour le conteneur.', '{\"couleur\":\"Vert foncé\",\"portes\":\"Porte à ouverture facile\"}', NULL, 'uploads/standard/principales/principale_standard_695d699006170_1767729552.webp', '[\"uploads\\/standard\\/secondaires\\/secondaire_standard_695d69900f959_1767729552.webp\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_695d699018163_1767729552.webp\"]', 'disponible', '2026-01-06 19:59:12', '2026-01-06 19:59:12', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
