(43, 'Conteneur de stockage 20DC – TALLINN (2020)', 1, 'standard', '20′ (6 mètres)', '20', 'DC', NULL, NULL, 6.06, 2.44, 2.59, 2200.00, 33.00, NULL, 900.00, NULL, 12, 5, 'occasion', NULL, 0, 'Vente de conteneurs maritimes « occasion» SENS UNIQUE\r\nVente de conteneurs maritimes. Tous nos conteneurs sont fabriqués en Asie. Les conteneurs neufs arrivent à notre terminal avec un chargement à sens unique afin d\'éviter les frais de transport qui seraient autrement répercutés sur le prix du conteneur.\r\n\r\nGarantie de résistance aux intempéries pendant 50 ans.\r\nLes images correspondent au contenant présenté dans la publicité.\r\nLe conteneur peut présenter de légers défauts esthétiques dus au transport.\r\nLe conteneur maritime possède un total de four maillons et peut être équipé de plus de 3 serrures.\r\nLe conteneur de stockage possède un total de trois maillons, qui sont plus hauts que ceux du conteneur maritime et peuvent également être équipés de plus de 3 serrures.\r\nLa protection de la serrure est située au milieu des deux portes.\r\nVentilation supplémentaire sur les côtés.\r\nLa location de conteneurs maritimes est possible sur accord.\r\nGarantie du meilleur prix !\r\nNous faisons toujours la meilleure offre pour un conteneur équivalent.\r\n\r\nVente de conteneurs maritimes – Transport et levage ?\r\nAprès avoir choisi le conteneur adapté, nous assurons également son transport.\r\nNous utilisons généralement  des camions-grues  ou  des chargeurs latéraux  .  Pour les zones les plus difficiles d\'accès,\r\nnous avons recours au  chargeur RAM\r\n. Après votre achat, nous stockons gratuitement votre conteneur dans notre terminal pendant six mois maximum,\r\nnotamment si le site de livraison n\'est pas encore prêt ou accessible.\r\n\r\nGarantie du meilleur prix – nous vous faisons toujours la meilleure offre pour le conteneur.', '{\"matiere\":\"acier CORTEN\",\"couleur\":\"Rouge brun\",\"portes\":\"Porte à ouverture facile\"}', NULL, 'uploads/standard/principales/principale_standard_695d76ac823d2_1767732908.jpeg', '[\"uploads\\/standard\\/secondaires\\/secondaire_standard_695d76ac86e99_1767732908.jpeg\"]', 'disponible', '2026-01-06 20:55:08', '2026-01-06 20:55:08', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(44, 'Contenitore di stoccaggio 20DC TALLINN (2019)', 1, 'standard', '20′ (6 mètres)', '20', 'DC', NULL, NULL, 6.06, 2.44, 2.59, 2200.00, 33.00, NULL, 900.00, NULL, 12, 5, 'occasion', '2019', 1, 'Vendita di container marittimi “usati” SENS UNIQUE\r\nVendita di container marittimi. Tutti i nostri container sono fabbricati in Asia. I container nuovi arrivano al nostro terminal con un carico a senso unico per evitare i costi di trasporto che altrimenti si ripercuoterebbero sul prezzo del container.\r\n\r\nGaranzia di resistenza alle intemperie per 50 anni.\r\nLe immagini corrispondono al contenitore presentato nella pubblicità.\r\nIl container può presentare lievi difetti estetici dovuti al trasporto.\r\nIl container marittimo ha un totale di quattro maglie e può essere dotato di più di 3 serrature.\r\nIl container di stoccaggio ha un totale di tre maglie, che sono più alte di quelle del container marittimo e possono anche essere dotate di più di 3 serrature.\r\nLa protezione della serratura si trova al centro delle due porte.\r\nVentilazione supplementare sui lati.\r\nIl noleggio di container marittimi è possibile previo accordo.\r\nGaranzia del miglior prezzo!\r\nFacciamo sempre l\'offerta migliore per un container equivalente.\r\nVendita di container marittimi - Trasporto e sollevamento?\r\nDopo aver scelto il container adatto, provvediamo anche al suo trasporto.\r\nUtilizziamo generalmente  autocarri con gru  o  carrelli elevatori laterali  ..\r\n Dopo l\'acquisto, immagazziniamo gratuitamente il vostro container nel nostro terminal per un massimo di sei mesi,\r\nin particolare se il luogo di consegna non è ancora pronto o accessibile.', '{\"matiere\":\"acciaio CORTEN\",\"portes\":\"Porta di facile apertura\"}', NULL, 'uploads/standard/principales/principale_standard_695d79cd868c2_1767733709.jpeg', '[\"uploads\\/standard\\/secondaires\\/secondaire_standard_695d79cd8ae01_1767733709.jpeg\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_695d79cd8ef87_1767733709.jpeg\"]', 'disponible', '2026-01-06 21:08:29', '2026-01-18 16:53:18', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(45, 'Conteneur de stockage 20DC TALLINN (2024)', 1, 'standard', '20′ (6 mètres)', '20', 'DC', NULL, NULL, 6.06, 2.44, 2.59, 2200.00, 33.00, NULL, 2090.00, NULL, 42, 5, 'neuf', '2024', 1, 'Vente de conteneurs maritimes « NEUF » SENS UNIQUE\r\nVente de conteneurs maritimes. Tous nos conteneurs sont fabriqués en Asie. Les conteneurs neufs arrivent à notre terminal avec un chargement à sens unique afin d\'éviter les frais de transport qui seriaient autrement répercutés sur le prix du conteneur.\r\n\r\nGarantie de résistance aux intempéries pendant 50 ans.\r\nLes images correspondent au contenant présenté dans la publicité.\r\nLe conteneur peut présenter de légers défauts esthétiques dus au transport.\r\nLe conteneur maritime possède un total de four maillons et peut être équipé de plus de 3 serrures.\r\nLe conteneur de stockage possède un total de trois maillons, qui sont plus hauts que ceux du conteneur maritime et peuvent également être équipés de plus de 3 serrures.\r\nLa protection de la serrure est située au milieu des deux portes.\r\nVentilation supplémentaire sur les côtés.\r\nLa location de conteneurs maritimes est possible sur accord.\r\nGarantie du meilleur prix !\r\nNous faisons toujours la meilleure offre pour un conteneur équivalent.\r\n\r\nVente de conteneurs maritimes – Transport et levage ?\r\nAprès avoir choisi le conteneur adapté, nous assurons également son transport.\r\nNous utilisons généralement  des camions-grues  ou  des chargeurs latéraux  .  Pour les zones les plus difficiles d\'accès,\r\nnous avons recours au  chargeur RAM\r\n. Après votre achat, nous stockons gratuitement votre conteneur dans notre terminal pendant six mois maximum,\r\nnotamment si le site de livraison n\'est pas encore prêt ou accessible.\r\n\r\nGarantie du meilleur prix – nous vous faisons toujours la meilleure offre pour le conteneur.', '{\"matiere\":\"acier CORTEN\",\"couleur\":\"Gris foncé\",\"portes\":\"Porte à ouverture facile\"}', NULL, 'uploads/standard/principales/principale_standard_695d7f6aca261_1767735146.jpeg', '[\"uploads\\/standard\\/secondaires\\/secondaire_standard_695d7f6ace5c4_1767735146.jpeg\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_695d7f6ad3074_1767735146.jpeg\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_695d7f6ad6bfc_1767735146.jpeg\"]', 'disponible', '2026-01-06 21:32:26', '2026-01-06 21:32:26', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
