(47, 'Conteneur maritime 20DC', 1, 'standard', '20′ (6 mètres)', '20', 'DC', NULL, NULL, 6.00, 2.43, 2.59, 1270.00, 33.00, NULL, 2690.00, NULL, 42, 1, 'neuf', '2023', 1, 'Vente de conteneurs maritimes « NEUF » SENS UNIQUE\r\nVente de conteneurs maritimes. Tous nos conteneurs sont fabriqués en Asie. Les conteneurs neufs arrivent à notre terminal avec un chargement à sens unique afin d\'éviter les frais de transport qui seraient autrement répercutés sur le prix du conteneur.\r\n\r\nGarantie de résistance aux intempéries pendant 50 ans.\r\nLes images correspondent au contenant présenté dans la publicité.\r\nLe conteneur peut présenter de légers défauts esthétiques dus au transport.\r\nLe conteneur maritime possède un total de four maillons et peut être équipé de plus de 3 serrures.\r\nLe conteneur de stockage possède un total de trois maillons, qui sont plus hauts que ceux du conteneur maritime et peuvent également être équipés de plus de 3 serrures.\r\nLa protection de la serrure est située au milieu des deux portes.\r\nVentilation supplémentaire sur les côtés.\r\nLa location de conteneurs maritimes est possible sur accord.\r\nGarantie du meilleur prix !\r\nNous faisons toujours la meilleure offre pour un conteneur équivalent.\r\n\r\nVente de conteneurs maritimes – Transport et levage ?\r\nAprès avoir choisi le conteneur adapté, nous assurons également son transport.\r\nNous utilisons généralement  des camions-grues  ou  des chargeurs latéraux  .  Pour les zones les plus difficiles d\'accès,\r\nnous avons recours au  chargeur RAM\r\n. Après votre achat, nous stockons gratuitement votre conteneur dans notre terminal pendant six mois maximum,\r\nnotamment si le site de livraison n\'est pas encore prêt ou accessible.\r\n\r\nGarantie du meilleur prix – nous vous faisons toujours la meilleure offre pour le conteneur.', '{\"matiere\":\"acier CORTEN\",\"couleur\":\"Bleu\",\"portes\":\"Porte à ouverture facile\"}', NULL, 'uploads/standard/principales/principale_standard_695d87c3de549_1767737283.jpeg', '[\"uploads\\/standard\\/secondaires\\/secondaire_standard_695d87c3e697c_1767737283.jpeg\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_695d87c3efb57_1767737283.jpeg\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_695d87c402f7e_1767737284.jpeg\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_695d87c40b186_1767737284.jpeg\"]', 'disponible', '2026-01-06 22:08:04', '2026-01-06 22:08:04', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(48, 'Conteneur maritime 20DC – TARTU', 1, 'standard', '20′ (6 mètres)', '20', 'DC', NULL, NULL, 6.06, 2.44, 2.59, 2200.00, 33.00, NULL, 2690.00, NULL, 42, 1, 'neuf', NULL, 0, 'Vente de conteneurs maritimes « NEUF » SENS UNIQUE\r\nVente de conteneurs maritimes. Tous nos conteneurs sont fabriqués en Asie. Les conteneurs neufs arrivent à notre terminal avec un chargement à sens unique afin d\'éviter les frais de transport qui seraient autrement répercutés sur le prix du conteneur.\r\n\r\nGarantie de résistance aux intempéries pendant 50 ans.\r\nLes images correspondent au contenant présenté dans la publicité.\r\nLe conteneur peut présenter de légers défauts esthétiques dus au transport.\r\nLe conteneur maritime possède un total de four maillons et peut être équipé de plus de 3 serrures.\r\nLe conteneur de stockage possède un total de trois maillons, qui sont plus hauts que ceux du conteneur maritime et peuvent également être équipés de plus de 3 serrures.\r\nLa protection de la serrure est située au milieu des deux portes.\r\nVentilation supplémentaire sur les côtés.\r\nLa location de conteneurs maritimes est possible sur accord.\r\nGarantie du meilleur prix !\r\nNous faisons toujours la meilleure offre pour un conteneur équivalent.\r\n\r\nVente de conteneurs maritimes – Transport et levage ?\r\nAprès avoir choisi le conteneur adapté, nous assurons également son transport.\r\nNous utilisons généralement  des camions-grues  ou  des chargeurs latéraux  .  Pour les zones les plus difficiles d\'accès,\r\nnous avons recours au  chargeur RAM\r\n. Après votre achat, nous stockons gratuitement votre conteneur dans notre terminal pendant six mois maximum,\r\nnotamment si le site de livraison n\'est pas encore prêt ou accessible.\r\n\r\nGarantie du meilleur prix – nous vous faisons toujours la meilleure offre pour le conteneur.', '{\"matiere\":\"acier CORTEN\",\"couleur\":\"Gris clair\",\"portes\":\"Porte à ouverture facile\"}', NULL, 'uploads/standard/principales/principale_standard_695d8ce4cec32_1767738596.jpeg', '[\"uploads\\/standard\\/secondaires\\/secondaire_standard_695d8ce4d7272_1767738596.jpeg\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_695d8ce4df39d_1767738596.jpeg\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_695d8ce4e6d9d_1767738596.jpeg\"]', 'disponible', '2026-01-06 22:29:56', '2026-01-06 22:29:56', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(49, 'CONTENITORE DI STOCCAGGIO 10DC', 1, 'standard', '10DC', '10', 'DC', NULL, NULL, 3.00, 2.44, 2.59, 1500.00, 19.00, NULL, 1500.00, NULL, 3000, 5, 'neuf', NULL, 0, 'Vendita di container per lo stoccaggio.\r\n\r\nIl container per lo stoccaggio 10DC è una soluzione nuova ed efficiente per un giardino o uno spazio commerciale.\r\n\r\nTutti i container sono prodotti in Asia.\r\n\r\nResistente alle intemperie per 50 anni.\r\nLe immagini corrispondono al container mostrato nell\'annuncio.\r\nIl container per lo stoccaggio ha due ante, più alte di quelle di un container per il trasporto marittimo, e può anche essere dotato di tre serrature.\r\nLa protezione della serratura si trova tra le due porte.\r\nÈ prevista una ventilazione aggiuntiva sui lati.\r\nIl noleggio di container per il trasporto marittimo è disponibile su richiesta.\r\n\r\nMiglior prezzo garantito!\r\n\r\nOffriamo sempre la migliore offerta per un container equivalente\r\n\r\nVendita di container per lo stoccaggio 10DC – Trasporto e sollevamento?\r\n\r\nDopo aver scelto il container giusto, possiamo anche organizzare il trasporto.\r\n\r\nIn genere utilizziamo autogru o carrelli elevatori laterali. Per le situazioni di accesso più difficili,\r\n\r\nutilizziamo una terna RAM.\r\n\r\nDopo l\'acquisto, conserveremo il vostro container presso il nostro terminal gratuitamente fino a sei mesi.\r\n\r\nÈ sempre possibile concordare un periodo più lungo,\r\nad esempio, se il sito non è ancora pronto o accessibile per la consegna del container.\r\n\r\nIn questo caso, il prezzo del container rimane invariato e avete la garanzia di ricevere il container selezionato alla data concordata.\r\n\r\nMiglior prezzo garantito: vi offriamo sempre la migliore offerta sul container', '{\"matiere\":\"acciaio\",\"couleur\":\"Rosso\",\"portes\":\"Porta ad apertura facilitata\"}', NULL, 'uploads/standard/principales/principale_standard_695e2909efb11_1767778569.jpeg', '[\"uploads\\/standard\\/secondaires\\/secondaire_standard_695e290a060e3_1767778570.jpeg\",\"uploads\\/standard\\/secondaires\\/secondaire_standard_695e290a1032d_1767778570.jpeg\"]', 'disponible', '2026-01-07 09:36:10', '2026-01-07 09:36:10', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
