INSERT INTO `messages_contact` (`id`, `nom`, `prenom`, `email`, `telephone`, `sujet`, `message`, `statut`, `date_creation`, `date_reponse`, `reponse`, `admin_id`) VALUES
(13, 'Palmer', 'Palmer', 'palmerrobert256@gmail.com', '', 'Achat', 'ujkiH', 'non_lu', '2026-03-16 16:27:47', NULL, NULL, NULL),
(14, 'Kim', 'Oliver', 'oliver@reviewremoval.uk', '+447575802542', 'Online-Reputationsmanagement Bewertungen & Bewertungsentfernung', 'Le recensioni negative o ingiuste possono influenzare seriamente la reputazione della tua attività e ridurre la fiducia dei clienti. Molti clienti leggono le recensioni prima di scegliere un servizio, e anche pochi commenti negativi possono influenzare la loro decisione e abbassare la tua valutazione complessiva.\r\n\r\n\r\n\r\nAiutiamo le aziende a identificare e rimuovere recensioni false, fuorvianti o che violano le politiche, che potrebbero danneggiare la loro reputazione. Questo include recensioni che non rispettano le linee guida delle piattaforme o recensioni vecchie che continuano a influenzare il tuo profilo.\r\n\r\n\r\n\r\nAllo stesso tempo, supportiamo le aziende nel migliorare la loro presenza online aiutandole a ottenere feedback positivi su piattaforme importanti come Google, Yelp, TripAdvisor, Trustpilot, Glassdoor, Facebook e molte altre.\r\n\r\nSe le recensioni negative stanno influenzando l’immagine della tua attività, possiamo aiutarti a fare i passi giusti per migliorare la tua valutazione.\r\n\r\n\r\nContattaci\r\nEmail: oliver@reviewremoval.uk\r\n\r\n\r\nWhatsApp: https://wa.me/447575802542', 'non_lu', '2026-04-03 18:45:51', NULL, NULL, NULL),
(15, 'Ali', 'Asif', 'asif@rocketdigitaltech.com', '', 'Improve Your Search Engine Visibility', 'Hello http://containerequipmentservices.lt,\r\n \r\nI hope you’re doing well. I came across your business online and thought you might be interested in improving your visibility and traffic on search engines.\r\n \r\nWe specialize in helping businesses strengthen their online presence through effective SEO strategies.\r\n \r\nOnce you share your target keywords and target market, I’ll send a full proposal.\r\n \r\nWarm regards,\r\nAsif', 'non_lu', '2026-06-24 10:24:15', NULL, NULL, NULL),
(16, 'Sharma', 'Ashwani', 'ashwani@rocketdigitaltech.com', '', 'Let’s Boost Your Website Traffic', 'Hello http://containerequipmentservices.lt,\r\n \r\nI wanted to reach out to see if you’re open to exploring ways to grow your website traffic and boost online performance.\r\n \r\nWe offer customized SEO services that deliver measurable improvements.\r\n \r\nOnce you share your target keywords and target market, I’ll send a full proposal.\r\n \r\nBest Regards,\r\nAshwani', 'non_lu', '2026-06-24 10:24:31', NULL, NULL, NULL),
(17, 'Ali', 'Asif', 'asif@rocketdigitaltech.com', '', 'Improve Your Search Engine Visibility', 'Hello http://containerequipmentservices.lt,\r\n \r\nI hope you’re doing well. I came across your business online and thought you might be interested in improving your visibility and traffic on search engines.\r\n \r\nWe specialize in helping businesses strengthen their online presence through effective SEO strategies.\r\n \r\nOnce you share your target keywords and target market, I’ll send a full proposal.\r\n \r\nWarm regards,\r\nAsif', 'non_lu', '2026-07-01 16:58:30', NULL, NULL, NULL),
(18, 'Ali', 'Asif', 'asif@rocketdigitaltech.com', '', 'Improve Your Search Engine Visibility', 'Hello http://containerequipmentservices.lt,\r\n \r\nIf you’re looking to boost your website’s visibility, I can help you achieve top Google rankings.\r\n \r\nI’ll prepare a complete SEO plan with actionable steps and potential growth insights for your products or services.\r\n \r\nOnce you share your target keywords and target market, I’ll send a full proposal.\r\n \r\nBest Regards,\r\nAsif', 'non_lu', '2026-07-08 15:52:57', NULL, NULL, NULL),
(19, 'Parcha', 'Deepak', 'parchad78@gmail.com', '', 'Let’s redesign your website for better leads and conversions', 'Hello http://containerequipmentservices.lt,\r\n \r\nI came across your business online and wanted to reach out.\r\n\r\nIf you are considering improving your website design or creating a new website, we can help with modern, responsive, and user-friendly website development.\r\n\r\nPlease let me know if you would like to see our portfolio or discuss your requirements.\r\n \r\nBest Regards,\r\nDeepak', 'non_lu', '2026-07-08 18:46:22', NULL, NULL, NULL),
(20, 'kim', 'Oliver', 'oliver@reviewremoval.uk', '6151517371', 'Ottieni più recensioni positive', 'Ottieni più recensioni positive per il tuo profilo aziendale. Le recensioni positive migliorano il tuo posizionamento, rafforzano la tua reputazione e aumentano la fiducia dei clienti. L\'aggiunta di recensioni professionali aiuta la tua attività a comparire più in alto nei risultati di ricerca e ad attirare più clienti. Offriamo anche un servizio di rimozione delle recensioni negative.\r\nRispondi a questa email oppure contattaci su WhatsApp: https://wa.me/447575802542', 'lu', '2026-07-17 08:16:50', NULL, NULL, NULL),
(25, 'Ananya', 'Ananya', 'ananya@rocketdigitaltech.com', '496479845', 'Let’s Boost Your Website Traffic', 'Hello http://containerequipmentservices.lt,\r\n\r\nI wanted to reach out to see if you’re open to exploring ways to grow your website traffic and boost online performance.\r\n\r\nWe offer customized SEO services that deliver measurable improvements.\r\n\r\nOnce you share your target keywords and target market, I’ll send a full proposal.\r\n\r\nBest Regards,\r\nAnanya', 'lu', '2026-10-10 13:54:22', NULL, NULL, NULL);
