INSERT INTO `services` (`id`, `nom`, `type_service`, `description`, `prix_unitaire`, `unite_mesure`, `duree_estimee`, `image_url`, `conditions`, `statut`, `created_at`, `updated_at`) VALUES
(1, 'Trasporto container', 'trasporto', 'Trasporto professionale di container in tutta Europa con attrezzature specializzate.\r\n\r\nATTREZZATURE DISPONIBILI:\r\n- Sideloader e backloader per la movimentazione\r\n- Rimorchi Van Hool per container cisterna\r\n- Rimorchi Krone per container marittimi\r\n- 30 camion e 70 rimorchi disponibili\r\n- Attrezzatura RAM backloader per accessi difficili\r\n\r\nAREE DI INTERVENTO:\r\n- Tutta l\'Unione Europea\r\n- Trasporto porta a porta\r\n\r\nCERTIFICAZIONI:\r\n- ISO 9001:2015 (Sistema di gestione della qualità)\r\n- ISO 14001:2015 (Gestione ambientale)\r\n\r\nTEAM:\r\n- Autisti multilingue e qualificati\r\n- Servizio clienti premium\r\n- Rispetto dei 7 \"diritti\" della logistica', 350.00, 'trajet', 14, 'uploads/services/Trasporto_container.jpg', '- Trasporto disponibile in tutta l\'Unione Europea\r\n- Consegna porta a porta\r\n- Utilizzo di attrezzature specializzate in base al tipo di container\r\n- Soluzioni per accessi difficili con RAM backloader\r\n- Garanzia di consegna nel luogo concordato senza problemi\r\n- Azienda C.E.S. CONTAINER EQUIPMENT SERVICES SRL\r\n- Seguici su Facebook e Instagram', 'actif', '2025-11-13 16:34:58', '2026-01-30 16:28:33'),
(2, 'Noleggio container 20 pieds', 'Noleggio', 'Noleggio container 20 pieds per stoccaggio temporaneo o cantieri', 45.00, 'giorno', NULL, 'uploads/services/Noleggio_container.webp', 'CONDIZIONI DI NOLEGGIO:\r\n- Durata minima: 6 mesi (noleggi brevi con supplemento)\r\n- Container disponibili in diverse dimensioni: 10 piedi, 20 piedi, 40 piedi\r\n- Attrezzature varie a seconda delle esigenze\r\n- Stoccaggio gratuito fino a 6 mesi dopo l\'acquisto se si sceglie l\'opzione di acquisto successivo\r\n- Periodo prorogabile previo accordo\r\n\r\nCONTAINER REFRIGERATI:\r\n- Container refrigerati disponibili per il noleggio\r\n- Diverse configurazioni: porte refrigerate, porte standard\r\n- Tutte le dimensioni: 10 piedi, 20 piedi, 40 piedi\r\n- Attrezzature varie disponibili\r\n\r\nINFORMAZIONI PRATICHE:\r\n- Consultazione delle disponibilità nel nostro negozio online\r\n- Trasporto e installazione su preventivo\r\n- Possibilità di accordo per periodi più lunghi', 'actif', '2025-11-13 16:34:58', '2026-01-30 16:31:14'),
(3, 'Trasporto di merci pericolose', 'trasporto', 'C.E.S. CONTAINER garantisce il trasporto di merci pericolose (ADR, IMO) in Francia e all\'estero. Tutti i nostri veicoli e rimorchi per container sono omologati ADR (FL, AT, EX/II ed EX/III).\r\n\r\nOffriamo il trasporto sicuro di tutte le classi ADR di merci pericolose:\r\n- Esplosivi (Classe ADR 1)\r\n- Sostanze radioattive (Classe ADR 7)\r\n- Sostanze liquide pericolose in container cisterna\r\n\r\nServizi complementari:\r\n- Etichettatura ADR conforme dei container di merci pericolose\r\n- Trasporto di container refrigerati, cisterne, case modulari\r\n- Sollevamento con gru ou caricatore laterale\r\n- Soluzione RAM backloader per luoghi difficili\r\n\r\nLa nostra competenza:\r\n- Autisti professionisti formati ADR\r\n- Consulente di sicurezza designato in azienda\r\n- Assicurazione di responsabilità civile supplementare per il trasporto di esplosivi\r\n- Partner contrattuale delle forze militari', 75.00, 'unite', NULL, 'uploads/services/Trasporto_di.jpg', '- Tutti i veicoli certificati ADR\r\n- Trasporto di tutte le classi ADR (1, 1.4S, 1.1, 2, 3, 4, 5, 7, 9)\r\n- Contenitori cisterna disponibili\r\n- Trasporto nazionale e internazionale\r\n- Etichettatura ADR opzionale\r\n- Soluzioni per accessi difficili\r\n- Rispetto dei tempi di consegna', 'actif', '2025-11-13 16:34:58', '2026-01-30 16:37:31'),
(4, 'Backloader', 'trasporto', 'ContrattC.E.S. CONTAINER offre soluzioni uniche e innovative ai propri clienti. Dal 2000 siamo in grado di caricare container da 20 piedi (6 metri) in verticale, nonché di scaricarli e posizionarli a terra dietro al veicolo.\r\n\r\nCARATTERISTICHE ESCLUSIVE:\r\n- Carico verticale di container da 20 piedi\r\n- Scarico e posizionamento a terra\r\n- Capacità di sollevamento fino a 25.000 kg\r\n- Attrezzatura unica in Francia\r\n\r\nSOLUZIONI COMPLEMENTARI:\r\n- Sideloader per sollevamento orizzontale (fino a 32.000 kg)\r\n- Adattamento in base alle esigenze del cantiere\r\n- Intervento rapido in loco\r\n\r\nVANTAGGI:\r\n- Risparmio di tempo e spazio\r\n- Soluzione innovativa brevettata\r\n- Team esperto e qualificato\r\n- Attrezzature ad alte prestazionio di manutenzione annuale', 200.00, 'an', NULL, 'uploads/services/Backloader.jpg', 'CONDIZIONI DI INTERVENTO:\r\n- Peso massimo: 25.000 kg per backloader\r\n- Peso massimo: 32.000 kg per sideloader\r\n- Container standard da 20 piedi\r\n- Sito accessibile ai mezzi\r\n- Si consiglia di prenotare con 48 ore di anticipo\r\n\r\nAREE DI INTERVENTO:\r\n- Tutta la France\r\n- Dipartimento [il vostro dipartimento] e regioni limitrofe\r\n- Su preventivo per interventi specifici\r\n\r\nATTREZZATURE:\r\n- Backloader per posizionamento verticale\r\n- Sideloader per sollevamento orizzontale\r\n- Veicoli adatti ai container', 'actif', '2025-11-13 16:34:58', '2026-01-30 16:40:02'),
(5, 'Sideloaders', 'trasporto', 'I sideloader (noti anche come carrelli laterali o gru swinglift) hanno rivoluzionato il trasporto dei container grazie al loro design unico e alla loro eccezionale funzionalità.\r\n\r\nCARATTERISTICHE TECNICHE:\r\n- Capacità di sollevamento: fino a 32.000 kg (peso del container incluso)\r\n- Portata della gru idraulica: fino a 1 metro dal camion\r\n- Posizionamento preciso del container sul lato sinistro del veicolo\r\n- Adatto a tutti i tipi di container: 20′, 30′, 40′, 45′\r\n- Tipi supportati: DRY, HC, OT, PW, REF, TANK\r\n- Possibilità di trasportare contemporaneamente due container da 20′ (max 10.000 kg ciascuno)\r\n- Conforme alle normative ADR et IMO per le merci pericolose\r\n\r\nVANTAGGI:\r\n- Eccezionale manovrabilità in spazi ristretti\r\n- Accesso a zone di carico difficili\r\n- Massima precisione di posizionamento\r\n- Versatilità d\'uso', 50.00, 'unite', NULL, 'uploads/services/Sideloaders.jpg', 'CONDIZIONI DI UTILIZZO:\r\n- Specificare l\'orientamento desiderato delle porte del container (lato cabina o posteriore)\r\n- Comunicare preventivamente le dimensioni esatte del container\r\n- Rispettare le normative di trasporto\r\n- Verificare preventivamente l\'accessibilità del luogo di consegna\r\n- Confermare il peso totale prima dell\'ordine\r\n\r\nAREE SERVITE:\r\nTutta la regione - accesso garantito a zone complesse e spazi ristretti', 'actif', '2025-11-13 16:34:58', '2026-01-30 16:42:00'),
(6, 'gru', 'trasporto', 'La nostra flotta comprende un camion gru che ci consente di trasportare contemporaneamente due container marittimi, container di stoccaggio o cabine modulari ai nostri clienti.\r\n\r\nIl camion gru può sollevare container vuoti in spazi ristretti, su fondamenta preparate, blocchi o persino in cantine e buche preparate.\r\n\r\nVANTAGGIO ESCLUSIVO: se acquistate due container contemporaneamente, pagherete solo il trasporto di uno.\r\n\r\nDotato di serrature adeguate per mettere in sicurezza il container o la cabina modulare. Garanzia di consegna della merce nelle condizioni originali.\r\n\r\nLa nostra flotta comprende anche un caricatore posteriore RAM per raggiungere i luoghi più difficili.', 0.00, 'heure', NULL, 'uploads/services/gru.jpg', '- Possibilità di trasportare due container contemporaneamente\r\n- Sollevamento solo di container vuoti\r\n- Accesso a luoghi difficili con il caricatore posteriore RAM\r\n- Sicurezza ottimale durante il trasporto\r\n- Offerta speciale: trasporto gratuit du secondo container con l\'acquisto di due container\r\n- Si consiglia di prenotare con 48 ore di anticipo', 'actif', '2025-11-13 16:34:58', '2026-01-30 16:45:40'),
(7, 'RAM Backloader', 'trasporto', 'Soluzione innovativa per il trasporto di container con rimorchio su misura\r\n\r\nIl RAM Backloader è una combinazione unica di rimorchio specializzato e pick-up Dodge RAM, progettato per il trasporto di container con la massima efficienza e versatilità.\r\n\r\nCARATTERISTICHE:\r\n- Trasporto di container di stoccaggio, marittimi e metallici fino a 6 metri\r\n- Accesso a zone difficili da raggiungere (cantieri lontani, spazi urbani ristretti)\r\n- Capacità di carico: massimo 2.500 kg\r\n- Sistema di ribaltamento controllato anche su terreni erbosi\r\n- Sicurezza ottimale con posizionamento sicuro tra le guide\r\n\r\nDIMENSIONI:\r\n- Lunghezza piattaforma: 6 metri\r\n- Larghezza piattaforma: 2,5 metri\r\n- Lunghezza totale con veicolo: 15 metri\r\n\r\nIDEALE PER:\r\n- Consegne in zone con accessi limitati\r\n- Cantieri difficili da raggiungere\r\n- Siti naturali protetti\r\n- Centri urbani densamente popolati', 150.00, '', NULL, 'uploads/services/RAM_Backloader.jpg', 'CONDIZIONI DI UTILIZZO:\r\n- Specificare l\'orientamento desiderato delle porte del container (lato cabina o lato posteriore)\r\n- Terreno minimo richiesto per l\'accesso del veicolo\r\n- Peso massimo: 2.500 kg\r\n- Lunghezza massima: 6 metri\r\n- Si consiglia di prenotare con 48 ore di anticipo\r\n\r\nAREE SERVITE:\r\n[Inserire qui le aree geografiche coperte dalla vostra azienda]\r\n\r\nINFORMAZIONI AGGIUNTIVE:\r\nSu richiesta sono disponibili foto e video dimostrativi per illustrare le capacità del RAM Backloader.', 'actif', '2025-11-28 20:23:33', '2026-01-30 16:52:26'),
(8, 'Wheel Loader', 'autre', 'Servizio di noleggio wheel loader professionale per la movimentazione di container e materiali pesanti. Macchine di ultima generazione con operatori qualificati.', 250.00, 'giorno', NULL, 'uploads/services/Wheel_Loader.jpg', '- Noleggio minimo: 1 giorno\n- Operatore incluso\n- Manutenzione inclusa\n- Assicurazione RC', 'actif', '2025-11-29 10:14:54', '2026-01-30 16:55:21'),
(9, 'Deposito e Servizi', 'autre', 'Servizi di deposito container e gestione logistica completa. Aree di stoccaggio sicure e sorvegliate per container di tutte le dimensioni.', 50.00, 'mese', NULL, 'uploads/services/Deposito_Servizi.png', '- Stoccaggio minimo: 1 mese\n- Area sorvegliata 24/7\n- Assicurazione inclusa\n- Accesso controllato', 'actif', '2025-11-29 10:14:54', '2026-01-30 16:58:44'),
(10, 'Terminal Container', 'autre', 'Gestione terminal container completo con servizi di movimentazione, stoccaggio e distribuzione. Soluzioni integrate per la logistica portuale.', 0.00, 'progetto', NULL, 'uploads/services/Terminal_Container.webp', '- Servizio su misura\n- Preventivo personalizzato\n- Operazioni 24/7\n- Certificazioni ISO', 'actif', '2025-11-29 10:14:54', '2026-01-30 17:03:21'),
(11, 'Carichi Oversize', 'trasporto', 'Trasporto specializzato per carichi oversize e progetti speciali. Attrezzature specifiche per carichi di grandi dimensioni et peso eccezionale.', 500.00, 'trajet', NULL, 'uploads/services/Carichi_Oversize.png', '- Pianificazione avanzata\n- Permessi speciali inclusi\n- Scorta tecnica\n- Assicurazione speciale', 'actif', '2025-11-29 10:14:54', '2026-01-30 17:05:20'),
(12, 'Dichiarazioni', 'autre', 'Servizi di dichiarazioni doganali e documentazione per spedizioni internazionali. Consulenza esperta per l\'import/export di container.', 75.00, 'dichiarazione', NULL, 'uploads/services/Dichiarazioni.jpg', '- Documentazione completa\n- Supporto multilingue\n- Tempi rapidi\n- Garanzia conformità', 'actif', '2025-11-29 10:14:54', '2026-01-30 17:07:56'),
(18, 'RAM Backloader', 'trasporto', 'Soluzione innovativa per il trasporto di container con rimorchio su misura\r\n\r\nIl RAM Backloader è una combinazione unica di rimorchio specializzato e pick-up Dodge RAM, progettato per il trasporto di container con la massima efficienza e versatilità.\r\n\r\nCARATTERISTICHE:\r\n- Trasporto di container di stoccaggio, marittimi e metallici fino a 6 metri\r\n- Accesso a zone difficili da raggiungere (cantieri lontani, spazi urbani ristretti)\r\n- Capacità di carico: massimo 2.500 kg\r\n- Sistema di ribaltamento controllato anche su terreni erbosi\r\n- Sicurezza ottimale con posizionamento sicuro tra le guide\r\n\r\nDIMENSIONI:\r\n- Lunghezza piattaforma: 6 metri\r\n- Larghezza piattaforma: 2,5 metri\r\n- Lunghezza totale con veicolo: 15 metri\r\n\r\nIDEALE PER:\r\n- Consegne in zone con accessi limitati\r\n- Cantieri difficili da raggiungere\r\n- Siti naturali protetti\r\n- Centri urbani densamente popolati', 150.00, '', NULL, 'uploads/services/RAM_Backloader.jpg', 'CONDIZIONI DI UTILIZZO:\r\n- Specificare l\'orientamento desiderato delle porte del container (lato cabina o lato posteriore)\r\n- Terreno minimo richiesto per l\'accesso del veicolo\r\n- Peso massimo: 2.500 kg\r\n- Lunghezza massima: 6 metri\r\n- Si consiglia di prenotare con 48 ore di anticipo\r\n\r\nAREE SERVITE:\r\n[Inserire qui le aree geografiche coperte dalla vostra azienda]\r\n\r\nINFORMAZIONI AGGIUNTIVE:\r\nSu richiesta sono disponibili foto e video dimostrativi per illustrare le capacità del RAM Backloader.', 'actif', '2025-11-28 20:23:33', '2026-01-30 16:51:12');
